fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // An empty prefix always matches.
    if p.is_empty() {
        return true;
    }
    // If v is shorter than p, it cannot start with p.
    if v.len() < p.len() {
        return false;
    }
    // Check character by character.
    for (i, pc) in p.iter().enumerate() {
        if v[i] != *pc {
            return false;
        }
    }
    true
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered = Vec::new();
    for v in xs.into_iter() {
        if has_prefix(&v, &p) {
            filtered.push(v);
        }
    }
    filtered
}

